            # Each non-background rectangle is a filled-zero panel containing a seed pattern.
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 8 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            colored=[(y,x,grid[y][x]) for y,x in cells if grid[y][x] not in (0,8)]
            if not colored:
                continue
            color=colored[0][2]
            cr0=min(y for y,x,v in colored); cr1=max(y for y,x,v in colored)
            cc0=min(x for y,x,v in colored); cc1=max(x for y,x,v in colored)
            ph=cr1-cr0+1; pw=cc1-cc0+1
            mask={(y-cr0,x-cc0) for y,x,v in colored}
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if grid[y][x] == 0 and ((y-cr0)%ph,(x-cc0)%pw) in mask:
                        out[y][x]=color
    return out
